/* NHISA: buildless, accessible, responsive site. All interactions stay local.
   DESIGN_VARIANCE 5 / MOTION_INTENSITY 3 / VISUAL_DENSITY 4.
   The supplied SU Slate design system is the brand source of truth. */
(() => {
  'use strict';
  const $ = (selector, scope = document) => scope.querySelector(selector);
  const main = $('#main');
  const data = window.NHISA;
  const site = data.site || {};
  const contact = site.contact || {};
  const isTestVisible = person => person.published || (site.showTestInterviews && person.test);
  const reviewedDate = () => new Intl.DateTimeFormat('en-US',{month:'long',day:'numeric',year:'numeric',timeZone:'UTC'}).format(new Date(data.immigration.reviewed+'T12:00:00Z'));
  const escape = value => String(value ?? '').replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char]));
  const icon = (name, extra = '') => `<span class="icon ${extra}" style="--icon:url('assets/icons/${name}.svg')" aria-hidden="true"></span>`;
  // ↗ marks links that leave the site and open a new tab; → marks links within the site.
  const arrow = '<span aria-hidden="true">↗</span><span class="sr-only"> (opens in a new tab)</span>';
  const right = '<span aria-hidden="true">→</span>';
  function readStorage(key, fallback) { try { return JSON.parse(localStorage.getItem(key)) ?? fallback; } catch { return fallback; } }
  function writeStorage(key, value) { try { localStorage.setItem(key, JSON.stringify(value)); return true; } catch { return false; } }
  let saved = readStorage('nhisa-saved', []);
  let tasks = readStorage('nhisa-tasks', {});
  if (!Array.isArray(saved)) saved = [];
  if (!tasks || typeof tasks !== 'object' || Array.isArray(tasks)) tasks = {};
  let filter = 'All resources';
  let query = '';
  let alumniFilter = 'All conversations';
  let toastTimer;
  function toast(message) { const el = $('#toast'); el.textContent = message; el.classList.add('visible'); clearTimeout(toastTimer); toastTimer = setTimeout(() => el.classList.remove('visible'), 3000); }
  function resourceCard(resource) {
    const isSaved = saved.includes(resource.id);
    return `<article class="resource-card"><div class="resource-card-top">${icon(resource.icon, 'icon-orange')}<button class="bookmark-button" data-save="${resource.id}" aria-label="${isSaved ? 'Unsave' : 'Save'} ${escape(resource.name)}" aria-pressed="${isSaved}">${icon('bookmark', 'icon-small')}</button></div><span class="resource-category">${escape(resource.category)}</span><h3>${escape(resource.name)}</h3><p>${escape(resource.description)}</p><div class="resource-source">${escape(resource.source)}</div><a class="text-link" href="${escape(resource.url)}" ${resource.internal?'':'target="_blank" rel="noopener noreferrer"'}>${resource.internal?'Read the guide':'Explore resource'} ${resource.internal?right:arrow}</a></article>`;
  }
  function cta(title = 'Your next chapter is a shared one.', text = 'Bring your perspective. Find your people. Help shape a community that grows with you.') {
    return `<section class="container cta-section"><div class="cta-box"><div><h2>${title}</h2><p>${text}</p></div><a class="button" href="#/join">Get involved ${right}</a></div></section>`;
  }
  function pageIntro(label, title, description, extra = '') { return `<section class="page-intro"><div class="container"><div class="breadcrumb"><a href="#/">Home</a><span aria-hidden="true">/</span><span>${label}</span></div><h1>${title}</h1><p>${description}</p>${extra}</div></section>`; }
  const home = () => {
    const published = data.alumni.filter(person => person.published).length;
    const stepsVisual = data.steps.map((step,i) => `<div class="mini-step"><span class="num">0${i+1}</span><span class="small-line"></span>${escape(step.short)}</div>`).join('');
    const featured = data.resources.filter(r => r.featured);
    return `
    <div class="container"><section class="hero"><div class="hero-copy"><div class="eyebrow">Newhouse International Student Association</div><h1>A new place.<span class="serif">A shared future.</span></h1><p class="hero-description">A community and career resource hub for Newhouse international students and alumni: visa and work authorization basics, a step-by-step career roadmap, and the people who have been here before.</p><div class="hero-actions"><a class="button" href="#/support">Start the career roadmap ${right}</a><a class="text-link" href="#/about">About NHISA ${right}</a></div></div><figure class="hero-visual"><img class="hero-photo" src="assets/hero.webp" srcset="assets/hero-900.webp 900w, assets/hero.webp 1700w" sizes="(max-width: 760px) calc(100vw - 54px), 45vw" alt="Students sharing a conversation on Syracuse University's campus" width="800" height="533" fetchpriority="high" /><figcaption class="hero-image-footer"><p>Students on the Syracuse University campus</p>${icon('globe')}</figcaption></figure></section></div>
    <div class="quicknav-band"><div class="container">${immigrationEntry('home')}</div></div>
    <section class="container section"><div class="section-header"><div class="eyebrow">Made for your journey</div><h2>Big questions.<br />A place to start.</h2><p>Wherever you are in your Newhouse journey, you do not have to figure out the next step alone.</p></div><div class="pathways">
      <article class="path-card"><div class="path-card-visual"><div class="steps-visual" aria-hidden="true">${stepsVisual}</div></div><div class="path-card-body"><span class="path-card-label">Career roadmap</span><h3>Find your footing.</h3><p>${['Zero','One','Two','Three','Four','Five','Six','Seven','Eight','Nine','Ten'][data.steps.length]||data.steps.length} steps from your first LinkedIn profile to your next interview, with a checklist that saves your progress.</p><a class="text-link" href="#/support">Explore the roadmap ${right}</a></div></article>
      <article class="path-card"><div class="path-card-visual"><img src="assets/journey-900.webp" srcset="assets/journey-900.webp 900w, assets/journey.webp 1700w" sizes="(max-width: 440px) 100vw, (max-width: 760px) 45vw, 33vw" alt="Two students talking as they walk across Syracuse University's campus" width="900" height="600" loading="lazy" style="object-position:50% 30%" /></div><div class="path-card-body"><span class="path-card-label">Alumni connections</span><h3>People, not just profiles.</h3><p>${published ? 'Discover the stories, honest advice, and conversations that can help you see what comes next.' : 'We are collecting conversations with Newhouse international alumni. Share your path, or read the first stories when they are published.'}</p><a class="text-link" href="#/alumni">${published ? 'Read alumni conversations' : 'See how to take part'} ${right}</a></div></article>
      <article class="path-card"><div class="path-card-visual"><div class="library-visual" aria-hidden="true"><div class="mini-resource"><div class="mini-resource-top">${icon('suitcase','icon-orange')}<span>${data.resources.length} resources</span></div>${featured.map(r => `<div class="mini-resource-row">${escape(r.name)}</div>`).join('')}</div></div></div><div class="path-card-body"><span class="path-card-label">Career access</span><h3>A clearer way forward.</h3><p>Spend less time searching for where to start. Explore useful platforms, tools, and career support.</p><a class="text-link" href="#/careers">Browse the resource library ${right}</a></div></article>
    </div></section>
    <section class="community-section section"><div class="container community-layout"><img src="assets/community-900.webp" srcset="assets/community-900.webp 900w, assets/community.webp 1700w" sizes="(max-width: 760px) 100vw, 50vw" alt="A group of students walking toward Hinds Hall on Syracuse University's campus" width="900" height="600" loading="lazy" /><div class="intro-text"><div class="eyebrow">Many backgrounds. Common ground.</div><h2>A community that<br />gets the journey.</h2><p>A new country. A different career landscape. Plenty of questions. NHISA brings Newhouse international students and alumni closer to the resources, perspectives, and people that make a difference.</p><div class="values-line"><span>${icon('globe')}Global perspectives</span><span>${icon('group')}Shared experience</span></div><a class="text-link" href="#/about">Get to know us ${right}</a></div></div></section>
    <section class="container section"><div class="section-header section-header-row"><div><h2>A few good places to begin.</h2><p>Useful resources for the next thing on your list.</p></div><a href="#/careers" class="text-link">View all resources ${right}</a></div><div class="resource-feature-grid">${featured.map(resourceCard).join('')}</div></section>
    ${cta()}`;
  };
  function support() {
    return `${pageIntro('Career roadmap', 'Career roadmap', 'A practical starting point for your career journey, from introducing yourself online to preparing for the conversation that comes next.')}${immigrationEntry('support')}<div class="container support-layout"><aside class="step-sidebar" aria-label="Career roadmap"><h2>Your career roadmap</h2>${data.steps.map((step,i) => `<a class="step-link" href="#/support?step=${step.id}" ${i===0?'aria-current="step"':''}><span>0${i+1}</span><span>${step.short}</span></a>`).join('')}<p class="progress-caption" id="task-progress">${taskProgress()}</p><p class="support-overview">Your checklist is saved in this browser. Move through the steps at your own pace.</p></aside><div>${data.steps.map((step,i) => `<section class="step-content" id="step-${step.id}"><div class="step-heading"><span class="step-num">0${i+1}</span><h2>${step.name}</h2></div><p>${step.intro}</p><div class="task-list">${step.tasks.map((task,j) => `<label class="task-label"><input type="checkbox" data-task="${step.id}-${j}" ${tasks[`${step.id}-${j}`]?'checked':''} /><span>${escape(task)}</span></label>`).join('')}</div><div class="step-resources">${step.resources.map(id => { const resource = data.resources.find(r => r.id === id); return resource.internal ? `<a class="resource-chip" href="${escape(resource.url)}">${escape(resource.name)} ${right}</a>` : `<a class="resource-chip" href="${escape(resource.url)}" target="_blank" rel="noopener noreferrer">${escape(resource.name)} ${arrow}</a>`; }).join('')}</div></section>`).join('')}</div></div>${cta('Every next step is easier together.', 'A question, a new perspective, or a conversation. There is a place for you in this community.')}`;
  }
  function taskProgress() { return `${data.steps.reduce((sum,step) => sum + step.tasks.filter((_,i) => tasks[`${step.id}-${i}`]).length, 0)} of ${data.steps.reduce((sum,step) => sum + step.tasks.length,0)} steps checked`; }
  function immigrationEntry(context='library') {
    return `<aside class="immigration-entry ${context==='support'?'container immigration-entry-support':''} ${context==='home'?'immigration-entry-home':''}" aria-label="Visa and work authorization guide">${icon('globe','icon-orange')}<div><h2>Visa and work authorization guide</h2><p>F-1, CPT, OPT, STEM OPT, and H-1B explained, with application overviews and official sources. Sources reviewed ${reviewedDate()}.</p></div><a class="button button-outline" href="#/immigration">Read the guide ${right}</a></aside>`;
  }
  function officialLinks(ids) {
    return ids.map(id=>{const source=data.immigration.sources.find(item=>item.id===id);return `<a href="${escape(source.url)}" target="_blank" rel="noopener noreferrer">${escape(source.label)} ${arrow}</a>`;}).join('');
  }
  function immigration() {
    const guide=data.immigration;
    const reviewed=reviewedDate();
    return `${pageIntro('Visa and work authorization','Visa and work authorization','A starting point for student visas and work authorization, from arriving for study to exploring practical training and employer sponsorship.')}<div class="container immigration-page"><div class="immigration-context"><p>Educational information, not individual legal advice. Confirm your eligibility and timing with Syracuse International Services or qualified immigration counsel.</p><span>Sources reviewed <time datetime="${guide.reviewed}">${reviewed}</time></span></div><nav class="immigration-topics" aria-label="Visa and work authorization topics"><a href="#/immigration" data-topic="overview" aria-current="location">At a glance</a>${guide.topics.map(topic=>`<a href="#/immigration?topic=${topic.id}" data-topic="${topic.id}">${topic.short}</a>`).join('')}<a href="#/immigration?topic=questions" data-topic="questions">Common questions</a></nav><section class="immigration-overview" id="immigration-overview"><div class="section-header"><h2>Different options. A clearer picture.</h2><p>Your options depend on your status, program, and employment. Start with the distinction between studying, practical training, and employer-sponsored work.</p></div><div class="immigration-table-wrap" role="region" aria-label="Compare student status and work authorization" tabindex="0"><table class="immigration-table"><caption class="sr-only">Overview of F-1, CPT, OPT, STEM OPT, and H-1B. See each topic below for details and official sources.</caption><thead><tr><th scope="col">Topic</th><th scope="col">Typical context</th><th scope="col">Who is involved?</th></tr></thead><tbody>${guide.topics.map(topic=>`<tr><th scope="row"><a href="#/immigration?topic=${topic.id}">${topic.short} ${right}</a></th><td>${escape(topic.stage)}</td><td>${escape(topic.authority)}</td></tr>`).join('')}</tbody></table></div></section><div class="immigration-guides">${guide.topics.map(topic=>`<section class="immigration-guide" id="immigration-${topic.id}" aria-labelledby="immigration-heading-${topic.id}"><div class="immigration-guide-heading">${icon(topic.icon,'icon-orange')}<span>${topic.short}</span><h2 id="immigration-heading-${topic.id}">${escape(topic.title)}</h2></div><p class="immigration-guide-intro">${escape(topic.intro)}</p><h3 class="immigration-process-label">The application, at a glance</h3><ol class="immigration-process">${topic.steps.map(step=>`<li><h4>${escape(step.title)}</h4><p>${escape(step.text)}</p></li>`).join('')}</ol><p class="immigration-takeaway"><strong>Keep in mind</strong>${escape(topic.takeaway)}</p><div class="immigration-sources"><span>Official guidance</span>${officialLinks(topic.sources)}</div></section>`).join('')}</div><section class="immigration-faq" id="immigration-questions"><div class="section-header"><h2>A few common questions.</h2><p>Clear up the terms before you plan your next step.</p></div>${guide.faqs.map(faq=>`<details><summary>${escape(faq.question)}</summary><p>${escape(faq.answer)}</p><div class="immigration-sources">${officialLinks(faq.sources)}</div></details>`).join('')}</section><aside class="immigration-advising">${icon('group','icon-orange')}<div><h2>Make your next step an informed one.</h2><p>Bring your program details, I-20, and questions to Syracuse’s Center for International Services. Check the linked official pages for current forms, fees, and filing windows.</p><a class="text-link" href="https://experience.syracuse.edu/intercultural-collective/center-for-international-services/immigration-status/" target="_blank" rel="noopener noreferrer">Visit Syracuse International Services ${arrow}</a></div></aside><a class="text-link immigration-back" href="#/careers?filter=international">${icon('arrow-left','icon-small')} Browse international student resources</a></div>`;
  }
  function careers(params) {
    filter = params.get('filter') === 'saved' ? 'Saved' : params.get('filter')==='international'?'International students':'All resources'; query = '';
    return `${pageIntro('Career access', 'Career access', 'Keep useful career resources in one place. Explore university support, professional platforms, and tools for your next application.', `<form id="resource-search" class="search-bar" role="search"><label class="search-field">${icon('magnifying-glass','icon-small')}<input id="resource-query" type="search" aria-label="Search resources" placeholder="Search resources, tools, or topics…" autocomplete="off" /></label><button class="button" type="submit">Search <span aria-hidden="true">→</span></button></form>`)}<section class="container" aria-label="Resource library"><div class="filter-bar"><div class="filter-chips" aria-label="Filter resources">${['All resources','Career advising','Job platforms','Networking','Application tools','International students','Saved'].map(name => `<button class="filter-chip" data-filter="${name}" aria-pressed="${filter===name}">${name==='Saved'?'Saved resources':name}</button>`).join('')}</div><p class="result-count" id="result-count" aria-live="polite"></p></div><div class="library-grid" id="library-results">${libraryResults()}</div><p class="resource-notice">This is a resource directory. Resources open on their original websites and may require a university sign-in. Alumni-shared opportunities will be added as the community grows.</p></section>${cta('Know a resource that helped you?', 'Good advice travels further when we share it. Help us make the next student’s starting point a little clearer.')}`;
  }
  function filteredResources() { return data.resources.filter(resource => (filter==='All resources'||(filter==='Saved'?saved.includes(resource.id):resource.category===filter)) && `${resource.name} ${resource.description} ${resource.category} ${resource.source}`.toLowerCase().includes(query.toLowerCase())); }
  function libraryResults() {
    const results = filteredResources();
    if (results.length) return (filter==='International students'&&!query?immigrationEntry():'')+results.map(resourceCard).join('');
    return `<div class="empty-state">${icon(filter==='Saved'?'bookmark':'magnifying-glass','icon-orange')}<h2>${filter==='Saved'?'Keep your good finds here.':'A different search might help.'}</h2><p>${filter==='Saved'?'Use the bookmark button on any resource to save it in this browser.':'No resources match these filters. Try a broader topic or clear your search.'}</p><button class="button button-outline" id="reset-filters">Explore all resources ${right}</button></div>`;
  }
  function updateLibrary() { $('#library-results').innerHTML = libraryResults(); $('#result-count').textContent = `${filteredResources().length} resource${filteredResources().length===1?'':'s'}`; document.querySelectorAll('[data-filter]').forEach(button => button.setAttribute('aria-pressed', button.dataset.filter===filter)); }
  const storyThemes = [
    {id:'first-steps', category:'Career beginnings',title:'The first step is rarely a straight line.',description:'The conversations we are building: first roles, lessons learned, and finding your direction.',image:'journey',alt:'Students talking together on the Syracuse campus'},
    {id:'coffee-chats',category:'Conversations and connections',title:'A coffee. A question. A new perspective.',description:'A space for honest conversations with Newhouse alumni and communications professionals.',image:'courtyard',alt:'Students gathered at an outdoor table beneath an orange umbrella'},
    {id:'shared-stories',category:'Life beyond Newhouse',title:'Different paths. A familiar starting point.',description:'Stories about taking a Newhouse experience into the working world, wherever that leads.',image:'students',alt:'Students walking together outside a Syracuse University building'}
  ];
  function alumni() {
    alumniFilter = 'All conversations';
    return `${pageIntro('Alumni connections', 'Alumni connections', 'Conversations with Newhouse international alumni about career beginnings, honest advice, and the lessons that travel with you beyond Newhouse.')}<section class="container alumni-lead">${data.alumni.some(isTestVisible) ? `${site.showTestInterviews&&data.alumni.some(person=>person.test)?'<div class="test-notice"><span class="test-label">TEST COLLECTION</span><p>Fictional people and interviews for this website preview. Campus photographs are illustrative.</p></div>':''}<div class="section-header"><div class="eyebrow">The people behind the paths</div><h2>Different journeys.<br />Something to share.</h2><p>Explore career beginnings, honest conversations, and the lessons that travel with you beyond Newhouse.</p></div><div class="alumni-filter-bar"><div class="filter-chips" aria-label="Filter alumni conversations">${['All conversations','Advertising','Public relations','Journalism','Media and production'].map(name=>`<button class="filter-chip" data-alumni-filter="${name}" aria-pressed="${name===alumniFilter}">${name}</button>`).join('')}</div><p class="result-count" id="alumni-count" aria-live="polite">${visibleAlumni().length} conversations</p></div><div class="story-grid profile-grid" id="alumni-results">${alumniResults()}</div>` : `<div class="alumni-call"><img src="assets/courtyard-900.webp" srcset="assets/courtyard-900.webp 900w, assets/courtyard.webp 1700w" sizes="(max-width: 760px) 100vw, 45vw" alt="Students talking at an outdoor table beneath an orange umbrella on Syracuse University's campus" width="900" height="600" /><div><h2>Alumni conversations are on the way.</h2><p>We are interviewing Newhouse international alumni about first roles, work authorization, and finding their footing in a new career landscape. The first conversations will appear here once they are approved for publication.</p><p>If you are a Newhouse alum or an industry professional, your experience could be someone’s starting point.</p><a class="button" href="#/join?role=alumni">Share your experience ${right}</a></div></div>`}</section>${cta('Your experience could be someone’s starting point.', 'Newhouse alumni and industry professionals: share a little of your journey and help the next generation find their way.')}`;
  }
  function visibleAlumni(){return data.alumni.filter(person=>isTestVisible(person)&&(alumniFilter==='All conversations'||person.field===alumniFilter));}
  function alumniResults(){const people=visibleAlumni();return people.length?people.map(person=>`<article class="story-card profile-card"><a class="profile-cover" href="#/alumni/profile/${encodeURIComponent(person.id)}" tabindex="-1" aria-hidden="true"><img src="${escape(person.photo)}" alt="" loading="lazy" width="600" height="700" /></a><div><div class="profile-category">${person.test?'<span class="test-label">TEST</span>':''}<small>${escape(person.field)}</small></div><h2><a href="#/alumni/profile/${encodeURIComponent(person.id)}">${escape(person.name)}</a></h2><p class="profile-role">${escape(person.role)} <span>· Class of ${escape(person.classOf)}</span></p><p>${escape(person.intro)}</p><a class="text-link" href="#/alumni/profile/${encodeURIComponent(person.id)}" aria-label="Read the conversation with ${escape(person.name)}">Read the conversation ${right}</a></div></article>`).join(''):`<div class="empty-state"><h2>A new conversation is on the way.</h2><p>Explore another field to find more perspectives.</p></div>`;}
  function storyPage(id) {
    const aliases = {'first-steps':'alex-lin','coffee-chats':'maya-chen','shared-stories':'jordan-park'};
    return aliases[id] ? profilePage(aliases[id]) : notFound();
  }
  function profilePage(id) {
    const person = data.alumni.find(person => person.id===id&&isTestVisible(person));
    if (!person) return notFound();
    return `${pageIntro('Alumni connections',escape(person.name),escape(person.intro))}<article class="container interview-article">${person.test?'<div class="test-notice"><span class="test-label">TEST INTERVIEW</span><p>This person, role, and interview are fictional examples. Campus imagery is illustrative.</p></div>':''}<div class="interview-layout"><aside class="interview-aside"><img src="${escape(person.photo)}" alt="${escape(person.photoAlt||person.name)}" width="700" height="800" /><p class="photo-note">${person.test?'Illustrative campus photography · test profile':escape(person.photoCredit||'')}</p><div class="profile-facts"><div><span>Field</span><strong>${escape(person.field)}</strong></div><div><span>Current role</span><strong>${escape(person.role)}</strong></div><div><span>Newhouse class</span><strong>${escape(person.classOf)}</strong></div><div><span>Based in</span><strong>${escape(person.location)}</strong></div></div></aside><div class="interview-body"><div class="eyebrow">A Newhouse conversation ${person.test?'· TEST':''}</div><h2>${escape(person.headline)}</h2><p class="interview-intro">${escape(person.background)}</p>${person.quote?`<blockquote>“${escape(person.quote)}”<cite>${escape(person.name)}${person.test?' · Fictional test interview':''}</cite></blockquote>`:''}<div class="interview-questions">${(person.questions||[]).map(item=>`<section><h3>${escape(item.question)}</h3><p>${escape(item.answer)}</p></section>`).join('')}</div><a class="text-link" href="#/alumni">${icon('arrow-left','icon-small')} All alumni conversations</a></div></div><div class="interview-next"><h2>Another path. Another perspective.</h2><div class="resource-feature-grid">${data.alumni.filter(other=>other.id!==person.id&&isTestVisible(other)).slice(0,3).map(other=>`<a class="related-profile" href="#/alumni/profile/${encodeURIComponent(other.id)}"><span>${escape(other.field)}${other.test?' · TEST':''}</span><h3>${escape(other.name)}</h3><p>${escape(other.headline)}</p><strong>Meet ${escape(other.name.split(' ')[0])} ${right}</strong></a>`).join('')}</div></div></article>${cta()}`;
  }
  function about() {
    return `${pageIntro('About NHISA','About NHISA','A professional community and career resource hub created around the experience of Newhouse international students.')}<section class="container section"><div class="editorial-intro"><img src="assets/campus.webp" alt="The Barnes Center at The Arch on Syracuse University's campus" width="867" height="1300" /><div><h2>Make the journey<br />a little more connected.</h2><p>Finding your way in a new place comes with questions. Where do I start my career search? How do I meet people in my industry? What can I learn from someone who has been here before?</p><p>NHISA brings useful resources, alumni experiences, and career starting points into one place, with a focus on Newhouse international students.</p><a class="text-link" href="#/join">Be part of the community ${right}</a></div></div><div class="about-values"><div>${icon('book-open','icon-orange')}<h3>Practical support.</h3><p>Clear starting points for LinkedIn, applications, networking, and interview preparation.</p></div><div>${icon('group','icon-orange')}<h3>Human connections.</h3><p>A space to learn from alumni and professionals through thoughtful conversations and shared experience.</p></div><div>${icon('globe','icon-orange')}<h3>Global perspectives.</h3><p>A community that recognizes the experience international students bring to communications and beyond.</p></div></div></section>${cta()}`;
  }
  function join(params) {
    const draft = readStorage('nhisa-interest-draft', {});
    const safeDraft = draft&&typeof draft==='object'&&!Array.isArray(draft)?draft:{};
    const selectedRole = params.get('role')==='alumni'?'Alumni or industry professional':safeDraft.role||'Current student';
    return `${pageIntro('Get involved','Get involved','Whether you are finding your footing or sharing what you have learned, there is a place for you in this community.')}<div class="container join-layout"><aside class="join-aside"><img src="assets/orange-campus.webp" alt="A diverse group of students walking together across Syracuse University's campus" width="700" height="500" /><h2>Start with a hello.</h2><p>Students can find support and new perspectives. Alumni and professionals can help by sharing their experiences, resources, or interest in a future coffee chat.</p></aside><div class="form-card" id="interest-card"><h2>A little about you.</h2><p>${contact.email ? `Write a short introduction. Your email app will open with it addressed to the NHISA team, ready to send.` : contact.formUrl ? `Write a short introduction, then paste it into the NHISA sign-up form.` : `Write a short introduction to keep for the NHISA team. Contact details for sending it are being set up.`}</p><form id="interest-form"><div class="form-field"><label for="interest-name">Your name <span aria-hidden="true">*</span></label><input id="interest-name" name="name" autocomplete="name" required maxlength="100" value="${escape(safeDraft.name||'')}" /></div><div class="form-field"><label for="interest-email">Email address <span aria-hidden="true">*</span></label><input id="interest-email" name="email" type="email" autocomplete="email" required maxlength="200" placeholder="you@syr.edu" value="${escape(safeDraft.email||'')}" /></div><div class="form-field"><label for="interest-role">I am a…</label><select id="interest-role" name="role">${['Current student','Alumni or industry professional','Prospective student','Community supporter'].map(role=>`<option ${selectedRole===role?'selected':''}>${role}</option>`).join('')}</select></div><div class="form-field"><label for="interest-message">What brings you here? <span style="font-weight:400">(optional)</span></label><textarea id="interest-message" name="message" maxlength="2000" placeholder="A question, an idea, or something you would like to share…">${escape(safeDraft.message||'')}</textarea></div><button class="button" type="submit">Prepare my introduction ${right}</button><p class="form-note">This form creates a draft on your device. It does not send your details or register membership. You can copy or download your introduction to share with the NHISA team.</p></form></div></div>`;
  }
  function privacy() {
    return `${pageIntro('Privacy and accessibility','Privacy and accessibility','How this website handles your information and supports access.')}<article class="container privacy-content"><h2>Your information stays with you.</h2><p>This version of the NHISA website does not create accounts, send form submissions, or use analytics trackers. Bookmarks, checklist progress, and introductions you choose to save are stored in your browser on this device.</p><p>If you choose to send your introduction by email, your own email app opens with the message filled in. Nothing is sent until you send it there.</p><p>Introductions are prepared locally. You decide whether to copy, download, or share them. Clearing your browser’s site data removes saved resources, progress, and introduction drafts.</p><h2>Resources open on other websites.</h2><p>External links take you to the resource provider’s website. Those websites have their own privacy practices and may require university access. No sign-in credentials are collected by this website.</p><h2>Built for access.</h2><p>This site includes keyboard navigation, visible focus indicators, descriptive image text, clear form labels, and reduced-motion support. It adapts to small screens and text zoom.</p><button class="button button-outline" id="clear-local-data">Clear my saved data</button><p id="privacy-clear-status" role="status" style="margin-top:20px"></p></article>`;
  }
  function notFound() { return `<section class="container section empty-state"><h1>This path is still taking shape.</h1><p>Let us bring you back to a good place to begin.</p><a class="button" href="#/">Back to home ${right}</a></section>`; }
  function route() {
    const raw = location.hash.slice(1);
    if (raw && !raw.startsWith('/') && route.initialized) return;
    const hash = raw.startsWith('/') ? raw : '/';
    const [path, search=''] = hash.split('?');
    const params = new URLSearchParams(search);
    const section = path.split('/')[1]||'home';
    const pages = { home, support, immigration, careers:()=>careers(params), alumni, about, join:()=>join(params), privacy };
    let title = { home:'Newhouse International Student Association',support:'Career roadmap',immigration:'Visa and work authorization',careers:'Career access',alumni:'Alumni connections',about:'About NHISA',join:'Get involved',privacy:'Privacy and accessibility' }[section] || 'Find your next step';
    const segments = path.split('/').filter(Boolean);
    main.innerHTML = section==='alumni'&&segments[1] ? (segments[1]==='profile'?profilePage(decodeURIComponent(segments[2]||'')):storyPage(segments[1])) : (pages[section]||notFound)();
    if(section==='alumni'&&segments[1]==='profile'){const person=data.alumni.find(person=>person.id===decodeURIComponent(segments[2]||''));if(person&&isTestVisible(person))title=`${person.name}${person.test?' · TEST interview':''}`;}
    document.title = `${title} | NHISA`;
    document.querySelectorAll('[data-nav]').forEach(link=>{ if(link.dataset.nav===section)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current'); });
    closeMenu();
    window.scrollTo({top:0,behavior:'instant'});
    if(section==='careers')updateLibrary();
    if(section==='immigration'&&params.has('topic')){
      const topic=params.get('topic');
      if(topic==='questions'||data.immigration.topics.some(item=>item.id===topic)){
        document.querySelectorAll('[data-topic]').forEach(link=>{if(link.dataset.topic===topic)link.setAttribute('aria-current','location');else link.removeAttribute('aria-current');});
        requestAnimationFrame(()=>{
          $('#immigration-'+topic).scrollIntoView({behavior:'instant',block:'start'});
          const navigation=$('.immigration-topics');
          const current=$('[aria-current="location"]',navigation);
          if(current)navigation.scrollLeft=Math.max(0,current.offsetLeft-(navigation.clientWidth-current.offsetWidth)/2);
        });
      }
    }
    if(section==='support'&&params.has('step')){
      const step=data.steps.find(step=>step.id===params.get('step'));
      if(step){requestAnimationFrame(()=>$('#step-'+step.id).scrollIntoView({behavior:'instant',block:'start'}));document.querySelectorAll('.step-link').forEach(link=>{if(link.hash.endsWith('step='+step.id))link.setAttribute('aria-current','step');else link.removeAttribute('aria-current');});}
    }
    if(route.initialized)main.focus({preventScroll:true});
    route.initialized=true;
  }
  function closeMenu() { $('.primary-nav').classList.remove('open'); $('.menu-toggle').setAttribute('aria-expanded','false'); $('.menu-toggle').setAttribute('aria-label','Open navigation'); document.body.classList.remove('menu-open'); }
  $('.menu-toggle').addEventListener('click',()=>{ const open=$('.menu-toggle').getAttribute('aria-expanded')!=='true'; $('.primary-nav').classList.toggle('open',open); $('.menu-toggle').setAttribute('aria-expanded',String(open)); $('.menu-toggle').setAttribute('aria-label',open?'Close navigation':'Open navigation'); document.body.classList.toggle('menu-open',open); });
  document.addEventListener('keydown',event=>{if(event.key==='Escape'&&$('.primary-nav').classList.contains('open')){closeMenu();$('.menu-toggle').focus();}});
  document.addEventListener('click',event=>{
    if(event.target.closest('.skip-link')){event.preventDefault();main.focus();main.scrollIntoView({block:'start'});return;}
    const bookmark=event.target.closest('[data-save]');
    if(bookmark){const id=bookmark.dataset.save; const resource=data.resources.find(item=>item.id===id);if(!resource)return; const wasSaved=saved.includes(id);saved=wasSaved?saved.filter(item=>item!==id):[...saved,id]; const persisted=writeStorage('nhisa-saved',saved);document.querySelectorAll(`[data-save="${id}"]`).forEach(button=>{button.setAttribute('aria-pressed',String(!wasSaved));button.setAttribute('aria-label',`${wasSaved?'Save':'Unsave'} ${resource.name}`);});if($('#library-results')&&filter==='Saved')updateLibrary();toast(persisted?(wasSaved?'Resource removed from your saved list.':'Resource saved for later.'): 'Updated for this visit. Browser storage is unavailable.');}
    const filterButton=event.target.closest('[data-filter]');if(filterButton){filter=filterButton.dataset.filter;updateLibrary();}
    const alumniButton=event.target.closest('[data-alumni-filter]');if(alumniButton){alumniFilter=alumniButton.dataset.alumniFilter;$('#alumni-results').innerHTML=alumniResults();const count=visibleAlumni().length;$('#alumni-count').textContent=`${count} conversation${count===1?'':'s'}`;document.querySelectorAll('[data-alumni-filter]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.alumniFilter===alumniFilter)));}
    if(event.target.closest('#reset-filters')){filter='All resources';query='';$('#resource-query').value='';updateLibrary();}
    if(event.target.closest('#clear-local-data')){try{['nhisa-saved','nhisa-tasks','nhisa-interest-draft'].forEach(key=>localStorage.removeItem(key));saved=[];tasks={};$('#privacy-clear-status').textContent='Your saved resources, checklist progress, and introduction draft have been cleared.';}catch{$('#privacy-clear-status').textContent='Browser storage could not be accessed. Clear site data in your browser settings.';}}
    if(event.target.closest('#copy-introduction'))copyIntroduction();
    if(event.target.closest('#download-introduction'))downloadIntroduction();
  });
  document.addEventListener('input',event=>{if(event.target.id==='resource-query'){query=event.target.value.trim();updateLibrary();}});
  document.addEventListener('change',event=>{if(event.target.matches('[data-task]')){tasks[event.target.dataset.task]=event.target.checked;const persisted=writeStorage('nhisa-tasks',tasks);$('#task-progress').textContent=taskProgress();if(!persisted)toast('Progress is available for this visit. Browser storage is unavailable.');}});
  let introduction='';
  function sendOptions(persisted){
    const saved=persisted?'A draft is saved in this browser.':'Your draft is available for this visit.';
    if(contact.email){const href=`mailto:${contact.email}?subject=${encodeURIComponent('Hello from a new NHISA member')}&body=${encodeURIComponent(introduction)}`;return `<p>${saved} Send it to <strong>${escape(contact.email)}</strong> from your email app. Nothing is sent until you press send there.</p><a class="button" href="${escape(href)}">Send by email ${icon('envelope','icon-small')}</a>`;}
    if(contact.formUrl)return `<p>${saved} Copy it, then paste it into the NHISA sign-up form.</p><a class="button" href="${escape(contact.formUrl)}" target="_blank" rel="noopener noreferrer">Open the sign-up form ${arrow}</a>`;
    return `<p>${saved} NHISA contact details are being set up. Copy or download your introduction and keep it until then.</p>`;
  }
  function introductionText(draft){return `Hello NHISA,\n\nMy name is ${draft.name}.\nI am a: ${draft.role}.\nEmail: ${draft.email}\n\n${draft.message||'I would like to learn more about the community and how to get involved.'}\n\nThank you,\n${draft.name}\n`;}
  document.addEventListener('submit',event=>{
    if(event.target.id==='resource-search'){event.preventDefault();query=$('#resource-query').value.trim();updateLibrary();}
    if(event.target.id==='interest-form'){event.preventDefault();const form=new FormData(event.target);const draft=Object.fromEntries(form);draft.name=String(draft.name).trim();draft.email=String(draft.email).trim();draft.message=String(draft.message).trim();if(!draft.name){$('#interest-name').setCustomValidity('Please enter your name.');$('#interest-name').reportValidity();$('#interest-name').addEventListener('input',()=>$('#interest-name').setCustomValidity(''),{once:true});return;}const persisted=writeStorage('nhisa-interest-draft',draft);introduction=introductionText(draft);$('#interest-card').innerHTML=`<div class="draft-success"><h2 tabindex="-1" id="draft-heading">Your introduction is ready.</h2>${sendOptions(persisted)}<button class="button ${contact.email||contact.formUrl?'button-outline':''}" id="copy-introduction">Copy introduction</button><button class="button button-outline" id="download-introduction">Download introduction ${icon('download','icon-small')}</button><a class="text-link" href="#/join?edit=true">Edit my introduction ${right}</a></div>`;$('#draft-heading').focus();}
  });
  async function copyIntroduction(){try{if(!navigator.clipboard?.writeText)throw new Error('clipboard-unavailable');await navigator.clipboard.writeText(introduction);toast('Introduction copied. You can share it when you are ready.');}catch{toast('Copy is unavailable here. Download your introduction instead.');}}
  function downloadIntroduction(){const blob=new Blob([introduction],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const anchor=document.createElement('a');anchor.href=url;anchor.download='NHISA-introduction.txt';anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your introduction is ready to download.');}
  function renderContact(){
    const holder=$('#footer-contact'); if(!holder)return;
    const links=[];
    if(contact.email)links.push(`<a href="mailto:${escape(contact.email)}">${escape(contact.email)}</a>`);
    if(contact.instagram)links.push(`<a href="${escape(contact.instagram)}" target="_blank" rel="noopener noreferrer">Instagram ${arrow}</a>`);
    if(contact.linkedin)links.push(`<a href="${escape(contact.linkedin)}" target="_blank" rel="noopener noreferrer">LinkedIn ${arrow}</a>`);
    if(contact.wechat)links.push(`<span>WeChat: ${escape(contact.wechat)}</span>`);
    if(contact.formUrl)links.push(`<a href="${escape(contact.formUrl)}" target="_blank" rel="noopener noreferrer">Sign-up form ${arrow}</a>`);
    if(links.length){holder.innerHTML=`<h2>Contact</h2>${links.join('')}`;holder.hidden=false;}
  }
  renderContact();
  window.addEventListener('hashchange',route);
  route();
})();
